    """部分映射交叉（PMX），保证子代仍是合法排列。"""
    n = self.n
    a, b = sorted(self._rng.sample(range(n), 2))
    c1, c2 = p1[:], p2[:]

    def pmx_child(c, other):
        child = [None] * n
        child[a:b + 1] = c[a:b + 1]
        for i in range(a, b + 1):
            if other[i] not in child:
                pos = i
                while a <= pos <= b:
                    pos = c.index(other[pos])
                child[pos] = other[i]
        for i in range(n):
            if child[i] is None:
                child[i] = other[i]
        return child

    return pmx_child(p1, p2), pmx_child(p2, p1)

